const text = ($input.first().json.message?.text || '').trim();
const chatId = $input.first().json.message?.chat?.id;

const staticData = $getWorkflowStaticData('global');
if (!staticData.accounts) staticData.accounts = [];
if (!staticData.usage) staticData.usage = {};

let reply = '';

// 1. COMMAND: VIEW ALL ACCOUNTS (/list)
if (text.toLowerCase() === '/list' || text.toLowerCase() === 'list' || text.toLowerCase() === '/status') {
  if (staticData.accounts.length === 0) {
    reply = 'ℹ️ No email accounts stored yet.\n\nSend: mail-yourname@gmail.com, password-yourpassword to add one.';
  } else {
    reply = `📋 **Active Sender Accounts (${staticData.accounts.length}):**\n\n`;
    staticData.accounts.forEach((acc, i) => {
      const sent = staticData.usage[acc.email] || 0;
      reply += `${i + 1}. 📧 \`${acc.email}\`\n   ↳ Sent today: **${sent}/30** emails\n\n`;
    });
    reply += '💡 To delete an account, send:\n`/delete email@gmail.com`';
  }
}

// 2. COMMAND: DELETE AN ACCOUNT (/delete email)
else if (text.toLowerCase().startsWith('/delete') || text.toLowerCase().startsWith('/remove') || text.toLowerCase().startsWith('delete')) {
  const targetEmail = text.replace(/(\/delete|\/remove|delete)/i, '').trim().toLowerCase();
  const initialCount = staticData.accounts.length;
  staticData.accounts = staticData.accounts.filter(a => a.email.toLowerCase() !== targetEmail);

  if (staticData.accounts.length < initialCount) {
    delete staticData.usage[targetEmail];
    reply = `🗑️ Successfully deleted: ${targetEmail}\n\n📊 Remaining active accounts: ${staticData.accounts.length}`;
  } else {
    reply = `⚠️ Email not found: ${targetEmail}\n\nSend /list to see all stored email addresses.`;
  }
}

// 3. COMMAND: ADD / UPDATE AN ACCOUNT (mail-..., password-...)
else {
  const mailMatch = text.match(/mail[-:\s]+([^,\n\s]+)/i);
  const passMatch = text.match(/password[-:\s]+(.+)/i);

  if (mailMatch && passMatch) {
    const email = mailMatch[1].trim();
    const password = passMatch[1].trim();
    const existingIndex = staticData.accounts.findIndex(a => a.email.toLowerCase() === email.toLowerCase());

    if (existingIndex >= 0) {
      staticData.accounts[existingIndex].password = password;
      reply = `🔄 Updated password for: ${email}`;
    } else {
      staticData.accounts.push({ email: email, password: password });
      if (staticData.usage[email] === undefined) staticData.usage[email] = 0;
      reply = `✅ Successfully added sender email!\n\n📧 Email: ${email}\n📊 Total active sender accounts: ${staticData.accounts.length}`;
    }
  } else {
    reply = '🤖 **Telegram Email Manager Commands:**\n\n➕ **Add:**\n`mail-xyz@gmail.com, password-apppassword`\n\n📋 **View All:**\n`/list`\n\n🗑️ **Delete:**\n`/delete xyz@gmail.com`';
  }
}

return {
  json: {
    chatId: chatId,
    reply: reply
  }
};
